          submitOnce(() => {
            save.reset();
            return save.mutateAsync({ values, from: froms }).then(() => { setForm({}); setFroms({}); });
          });
        }}
      >
        {SETTING_KEYS.map((key) => (
          <div key={key}>
            <label>
