    .filter((c) => patrons.has(c.personId) && c.status === 'SETTLED' && c.settledDue !== null && from <= c.date && c.date <= today)
    .reduce((t, c) => t + Math.round(Number(c.settledDue) * 100), 0);
  return (cents / 100).toFixed(2);
}

/** Sum the amounts of the claims that count (see `counts`) exactly (in cents), shown with two decimals. */
export function sumAmounts(claims: Claim[]): string {
  const cents = claims.filter(counts).reduce((t, c) => t + Math.round(Number(c.amount) * 100), 0);
  return (cents / 100).toFixed(2);
}

/** A claim's due-by (yyyy-MM-dd), fixed when it was added. */
export const dueBy = (c: Claim): string => c.dueBy;

/** Whether a claim is overdue: it is open (OPEN or PENDING), not deferred, and its due-by is before the sheet's `today`. */
export const isOverdue = (c: Claim, today: string) =>
  isOpen(c) && !c.deferred && today !== '' && dueBy(c) < today;

/** How many of the selected claims a bulk open opened, and how many it refused (left as they were). */
export type BulkOpenResult = { opened: number; refused: number };

/** Open the selected claims together, numbered in list order (people in added order, newest claim
 *  first within a person); each that cannot be opened is left as it is and counted as refused. */
export function bulkOpenClaims(sheetId: string, by: string, claimIds: number[]): Promise<BulkOpenResult> {
  return postJson<BulkOpenResult>(`${sheetBase(sheetId)}/bulk-open?by=${encodeURIComponent(by)}`, { claimIds });
import { useQuery } from '@tanstack/react-query';
import { claimsKey, listClaims, liveClaims } from '../claims/api';
import { gradeOn, listPeople, peopleKey, type Person } from '../people/api';
import { useFloor, useLate } from '../settings/api';
import { useSheetToday } from '../sheet/api';
import { claimDue, listRates, overdue, ratesKey, trimmedSum } from './api';

/** The sheet's overdue claims: how many of the claims that count are OPEN past their due-by, and
 *  their due (with its late charge) added up per person, the sheet's total leaving out the single
 *  highest and lowest person's when there are three or more people. */
export function useOverdue(sheetId: string, user: string): ReturnType<typeof overdue> {
  const people = useQuery({ queryKey: peopleKey(sheetId), queryFn: () => listPeople(sheetId) });
  const claims = useQuery({ queryKey: claimsKey(sheetId), queryFn: () => listClaims(sheetId) });
  const rates = useQuery({ queryKey: ratesKey(sheetId), queryFn: () => listRates(sheetId) });
  const floor = useFloor(sheetId);
  const today = useSheetToday(sheetId, user);
  const charges = useLate(sheetId, today);
  const byId = new Map<number, Person>((people.data ?? []).map((p) => [p.id, p]));
  const live = liveClaims(claims.data ?? [], people.data).filter((c) => byId.has(c.personId));
  const dueOf = (c: Parameters<typeof claimDue>[0]) => claimDue(c, rates.data, (d) => gradeOn(byId.get(c.personId)!, d), floor, charges);
  const perPerson = (people.data ?? []).map((p) => overdue(live.filter((c) => c.personId === p.id), today, dueOf).total);
  return { count: overdue(live, today, dueOf).count, total: trimmedSum(perPerson) };
}

export function Overdue({ sheetId, user }: { sheetId: string; user: string }) {
  const late = useOverdue(sheetId, user);
  return (
    <p>
      Overdue <span data-testid="rollup-overdue-count">{late.count}</span>{' '}
      totalling <span data-testid="rollup-overdue-total">{late.total}</span>
    </p>
  );
}
